// Week rotation: week 0 = original bank (epoch Monday), then cycle through
// the extra banks. The active bank is copied into HOMEWORK_DATA IN PLACE so
// every existing reference keeps working.
(function () {
  var banks = [HOMEWORK_DATA];          // week 1 is the original bank
  WEEK_EXTRA_BANKS.forEach(function (b) { banks.push(b); });
  var epoch = Date.parse('2026-10-26');   // Monday of week 1
  var now = Date.now();
  var weekN = Math.floor((now - epoch) / (7 * 24 * 3600 * 1000));
  if (weekN < 0) weekN = 0;
  window.__weekNum = weekN;
  window.__bankId = weekN % banks.length;
  window.__ALL_BANKS = banks;
  var active = banks[window.__bankId];
  // Copy first, then clear: when the active bank IS the HOMEWORK_DATA
  // array (week 1), a naive clear-then-push would read an emptied array.
  var copy = active.slice();
  HOMEWORK_DATA.length = 0;
  copy.forEach(function (day) { HOMEWORK_DATA.push(day); });
})();
